    (9, 2), (10, 3), (10, 0)
}

# Add other Row 4 blockages except 9, 13, 14
for x in range(30):
    if x not in (9, 13, 14):
        solids_2f.add((x, 4))
# Add Row 16 solid from Column 14 to 20
for x in range(14, 21):
    solids_2f.add((x, 16))
# Row 8 solid from Column 3 to 12
for x in range(3, 13):
    solids_2f.add((x, 8))
# Row 8 solid from Column 16 to 21
for x in range(16, 22):
    solids_2f.add((x, 8))
# Row 10 solid from Column 13 to 22
for x in range(13, 23):
    solids_2f.add((x, 10))
# Row 12 solid from Column 13 to 22
for x in (13, 15, 16, 18, 19, 20, 21, 22):
    solids_2f.add((x, 12))

# Block Column 0 on 2F West as solid map border:
for y in range(18):
    solids_2f.add((0, y))

# Water-only coordinates on 1F
water_1f = set()
for x in range(30):
    for y in range(18):
        # Eastern canal
        if 22 <= x <= 25 and 4 <= y <= 8:
            water_1f.add((x, y))
        # Western canal
        elif 1 <= x <= 5 and 6 <= y <= 16:
            water_1f.add((x, y))
        # Central water canal and crossovers
        elif 8 <= x <= 11 and 6 <= y <= 15:
            water_1f.add((x, y))
        elif 9 <= x <= 15 and y == 7:
            water_1f.add((x, y))
        elif 9 <= x <= 15 and y == 6:
            water_1f.add((x, y))
        elif 14 <= x <= 22 and y in (4, 5):
            water_1f.add((x, y))

ramps = {(23, 3), (15, 3), (11, 13), (25, 9)}

# Clean up water coordinates that contain solid blockages or ramps
water_1f = water_1f - solids_1f - ramps

transitions = {
    # Southwest Ladder 6
    (3, 11, '0_228'): (3, 11, '0_226'),
    (3, 11, '0_226'): (3, 11, '0_228'),
    # Ladder 5
    (7, 1, '0_228'): (9, 1, '0_226'),
    (9, 1, '0_226'): (7, 1, '0_228'),
    # Ladder 3
    (18, 9, '0_228'): (19, 7, '0_226'),
    (19, 7, '0_226'): (18, 9, '0_228'),
    # Ladder 2
    (27, 1, '0_228'): (29, 1, '0_226'),
    (29, 1, '0_226'): (27, 1, '0_228'),
}

def get_neighbors(x, y, map_id, mode):
    neighbors = []
    solids = solids_1f if map_id == '0_228' else solids_2f

    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nx, ny = x + dx, y + dy
        if 0 <= nx < 30 and 0 <= ny < 18:
            if (nx, ny) not in solids:
                if map_id == '0_228':
                    is_water_tile = (nx, ny) in water_1f
                    is_ramp_tile = (nx, ny) in ramps

                    if mode == 'foot':
                        if is_water_tile:
                            if (x, y) in ramps:
                                neighbors.append((nx, ny, map_id, 'surf'))
                        else:
                            neighbors.append((nx, ny, map_id, 'foot'))
                    elif mode == 'surf':
                        if is_water_tile:
                            neighbors.append((nx, ny, map_id, 'surf'))
                        elif is_ramp_tile:
                            neighbors.append((nx, ny, map_id, 'foot'))
                else:
                    neighbors.append((nx, ny, map_id, mode))

    if (x, y, map_id) in transitions:
        tx, ty, t_map = transitions[(x, y, map_id)]
        neighbors.append((tx, ty, t_map, mode))

    return neighbors

def solve(start_map_id, start_x, start_y, target_map_id, target_x, target_y, mode):
    start_map = '0_228' if '228' in start_map_id else '0_226'
    target_map = '0_228' if '228' in target_map_id else '0_226'

    start_mode = mode
    if mode == 'auto':
        start_mode = 'surf' if (start_x, start_y) in water_1f and start_map == '0_228' else 'foot'

    start_state = (start_x, start_y, start_map, start_mode)
    queue = [[start_state]]
    visited = {start_state}

    while queue:
        path = queue.pop(0)
        curr = path[-1]
        cx, cy, cmap, cmode = curr

        if cx == target_x and cy == target_y and cmap == target_map:
            return path

        for nx, ny, nmap, nmode in get_neighbors(cx, cy, cmap, cmode):
            state = (nx, ny, nmap, nmode)
            if state not in visited:
                visited.add(state)
                queue.append(path + [state])

    return None

def path_to_buttons(path):
    buttons = []
    for i in range(len(path) - 1):
        cx, cy, cmap, cmode = path[i]
        nx, ny, nmap, nmode = path[i+1]

        if cmap != nmap:
            buttons.append('A')
            continue

        if cmode != nmode:
            if nmode == 'surf':
                buttons.append('Start')
                buttons.append('sleep 1000')
                buttons.append('Down')
                buttons.append('A')
                buttons.append('sleep 1000')
                buttons.append('A')
                buttons.append('sleep 1000')
                buttons.append('A')
                buttons.append('sleep 1500')
            else:
                pass

        if nx > cx: buttons.append('Right')
        elif nx < cx: buttons.append('Left')
        elif ny > cy: buttons.append('Down')
        elif ny < cy: buttons.append('Up')

    return buttons

try:
    if 'input_data' in globals():
        data = input_data
    elif len(sys.argv) > 1:
        data = json.loads(sys.argv[1])
    else:
        data = {}

    if data:
        start_map = data['start_map_id']
        start_x = int(data['start_x'])
        start_y = int(data['start_y'])
        target_map = data['target_map_id']
        target_x = int(data['target_x'])
        target_y = int(data['target_y'])
        mode = data['travel_mode']

        path = solve(start_map, start_x, start_y, target_map, target_x, target_y, mode)
        if path:
            buttons = path_to_buttons(path)
            print(json.dumps(buttons))
        else:
            print(json.dumps([]))
    else:
        print(json.dumps([]))
except Exception as e:
    print(json.dumps({"error": str(e)}))
